-- Add new authored content without overwriting administrator edits to existing items.
insert into private.tutor_library_items(id,kind,title,description,category,format,minutes,status,sections,lessons,supporting_resource_id)
select item->>'id',item->>'kind',item->>'title',item->>'description',item->>'category',item->>'format',(item->>'minutes')::integer,item->>'status',item->'sections',item->'lessons',item->>'supporting_resource_id'
from jsonb_array_elements('[{"id":"goal-design-guide","kind":"resource","title":"Design measurable learner goals","description":"Worked examples and a checklist for assessment, skill and practice goals in AeroGen learning plans.","category":"Assessment & progress","format":"Guide","minutes":8,"status":"published","sections":[{"heading":"Start with the learner and their course","body":"Open the subject plan and check the learner’s grade or phase, curriculum, module outline and starting evidence. Choose a narrow task that matters in that setting. Do not promise a particular school or university result."},{"heading":"Assessment-result example","body":"Goal: reach 70% on two independent checks of linear equations, at least seven days apart, by the agreed review date. Record the original mark and maximum. Use the agreed assessment category, topic scope, comparable difficulty and minimum question count. The first verified independent comparable result is the baseline. A change from 40% to 58% is 18 percentage points, not an 18% relative improvement."},{"heading":"Demonstrated-skill example","body":"Goal: apply the correct referencing method independently in two new assignments, at least seven days apart. Define the rubric criteria before reviewing work. Record whether the attempt was guided or independent. A guided attempt does not meet an independent demonstration goal."},{"heading":"Practice-habit example","body":"Goal: complete six agreed retrieval-practice activities before the review date. Specify what each activity involves and what counts as complete. This measures a practice habit; completion alone does not increase an assessed mark or skill level."},{"heading":"Use the app’s agreement and review flow","body":"Propose a goal with a target, specific success criteria and review date. Both participants approve the same proposal. Keep assessment scope stable after evidence is recorded. Use a new goal if scope changes; propose a reasoned revision for changes the existing goal can support. The learner controls access to the subject plan."},{"heading":"Review the evidence, then agree the next step","body":"Record relevant work or results, verify the source and conditions, and explain the next action. Separate confidence and time spent from assessed ability. Check progress at the review date. The form validates structure; the tutor must still judge the educational suitability of the goal."}],"lessons":[]},{"id":"goal-setting-lab","kind":"course","title":"Build trackable learner goals","description":"Practise choosing targets, success criteria and evidence that match AeroGen’s three goal types.","category":"Assessment & progress","format":"Self-study course","minutes":20,"status":"published","supporting_resource_id":"goal-design-guide","sections":[],"lessons":[{"id":"score-evidence","title":"Use comparable assessment evidence","body":"An assessment-result goal needs a starting result and later results measuring the same agreed scope under comparable conditions. The learner and tutor agree the target and the number and spacing of successful checks.","question":"Which evidence can measure an assessment-result goal?","options":["Hours spent studying the topic","A verified independent result from a comparable assessment in the agreed category","An unrelated module result with a higher mark"],"answer":1,"explanation":"Use verified, independent and comparable results. Study time and unrelated results cannot establish this goal’s academic improvement."},{"id":"skill-evidence","title":"Check an independent demonstration","body":"A skill goal describes a task and rubric that the learner can meet independently. Repeated demonstrations, spaced by the agreed minimum gap, provide stronger evidence than copying a worked example.","question":"What can count towards an independent skill goal?","options":["Copying the tutor’s worked example with prompts","Saying that the topic feels easier","Reviewed work meeting the agreed criteria without prompts"],"answer":2,"explanation":"The work must demonstrate the agreed skill independently. Guided practice is valuable preparation, but is not independent mastery."},{"id":"habit-evidence","title":"Measure a practice habit honestly","body":"A habit goal counts completion of agreed activities before the review date. It does not claim that a learner has mastered a skill or raised a school mark.","question":"What should completing the agreed practice activities update?","options":["The practice-habit goal only","Every skill in the learning plan","The learner’s school or university mark"],"answer":0,"explanation":"Activity completion measures the agreed habit. Academic improvement still needs assessment or reviewed skill evidence."}]}]'::jsonb)item
on conflict(id) do nothing;

